function IdolLive3D_TimeLineMarkerMgr:__init( timelineEnv_ )
    self.timelineEnv = timelineEnv_
    self.superTimelineEnv = timelineEnv_.superTimelineEnv
    self.nameMap = {}      -- < k:markerName, v:{name,time} >
    self.sortedList = {}   -- .time 递增排序
    self.currentIdx1Based = 1 --
    ---
    self.isSorted = false
end


-- 需外部调用 Delete()
function IdolLive3D_TimeLineMarkerMgr:__delete()
end


-- =====================================================================================================


function IdolLive3D_TimeLineMarkerMgr:AddMarker( name_, time_ )
    assert( IdolLive3D_Utils.IsKeyValid(name_) )
    local node = { name = name_, time = checkNumber(time_) }
    if self.nameMap[name_] ~= nil then 
        printError("发现 name 重复的 marker: " .. tostring(name_))
    end 
    self.nameMap[name_] = node
    table.insert( self.sortedList, node )
end

---@return table | nil
function IdolLive3D_TimeLineMarkerMgr:TryFindMarker( name )
    return self.nameMap[name]
end



function IdolLive3D_TimeLineMarkerMgr:Sort()
    if #self.sortedList == 0 then 
        return
    end
    -- 升序排序:
    table.sort( self.sortedList, function(a,b)
        return checkNumber(a.time) <= checkNumber(b.time)
    end )
    -- marker debug:
    print( "markers: ---------------------- clipId: " .. tostring(self.timelineEnv.clipId) )
    for i=1, #self.sortedList do 
        local node = self.sortedList[i]
        print("-- i:"..tostring(i).."; time = " ..tostring(node.time).."; name = " .. tostring(node.name))
    end 
    self.isSorted = true
end



function IdolLive3D_TimeLineMarkerMgr:Reset()
    self.currentIdx1Based = 1
end



function IdolLive3D_TimeLineMarkerMgr:SelfUpdate()
    if #self.sortedList == 0 then 
        return
    end
    if self.isSorted ~= true then 
        return
    end 
    ------- 
    if self.currentIdx1Based > #self.sortedList then -- 所有 marker 都遍历完了
        return
    end 
    
    -- 为简化系统, 一帧只触发一个 marker:
    local currentMarker = self.sortedList[self.currentIdx1Based]
    if self.timelineEnv.play.playTime > currentMarker.time then 
        --printError("触发 marker: " .. tostring(currentMarker.name))
        self.superTimelineEnv:OnTimelineMarker({ 
            markerName = currentMarker.name, 
            markerTime =  currentMarker.time,
            playCount0Based = self.timelineEnv.play.loopInteger,
            timelineEnv = self.timelineEnv
        })
        self.currentIdx1Based = self.currentIdx1Based + 1
    end 
end






return IdolLive3D_TimeLineMarkerMgr
